160. // `internal_inv` and recover `wf()` for the `inv()` postcondition through this lemma.
161. proof fn lemma_internal_inv_implies_wf(inner: &Inner)
162.     requires
163.         inner.internal_inv(),
164.     ensures
165.         inner@.wf(),
166. {
167.     let ps: int = spec_page_size();
168.     let v = inner@;
169.     let nbits: int = inner.bitmap@.num_bits;
170.     assert(ps > 0);
171.     assert(inner.bitmap.inv());
172.     assert(inner.bitmap@.wf());
173. 
174.     // Page-alignment of allocated/free addresses (each is `i * ps`).
175.     assert forall|addr: int| v.allocated_frames.contains(addr) implies addr % ps == 0 by {
176.         let i = choose|i: int|
177.             #[trigger] inner.bitmap@.set_bits.contains(i) && addr == frame_addr_of(i);
178.         assert(addr == i * ps);
179.         vstd::arithmetic::div_mod::lemma_mod_multiples_basic(i, ps);
180.     };
181.     assert forall|addr: int| v.free_frames.contains(addr) implies addr % ps == 0 by {
182.         let i = choose|i: int|
183.             0 <= i < nbits && !(#[trigger] inner.bitmap@.set_bits.contains(i))
184.                 && addr == frame_addr_of(i);
185.         assert(addr == i * ps);
186.         vstd::arithmetic::div_mod::lemma_mod_multiples_basic(i, ps);
187.     };
188. 
189.     // Disjointness of allocated and free frame sets.
190.     assert forall|addr: int| v.allocated_frames.contains(addr) implies !v.free_frames.contains(addr) by {
191.         let i = choose|i: int|
192.             #[trigger] inner.bitmap@.set_bits.contains(i) && addr == frame_addr_of(i);
193.         assert(addr == i * ps);
194.         if v.free_frames.contains(addr) {
195.             let j = choose|j: int|
196.                 0 <= j < nbits && !(#[trigger] inner.bitmap@.set_bits.contains(j))
197.                     && addr == frame_addr_of(j);
198.             assert(addr == j * ps);
199.             assert(i == j) by (nonlinear_arith) requires ps > 0, i * ps == j * ps;
200.             assert(false);
201.         }
202.     };
203. 
204.     // Allocated iff refcount entry exists and is positive.
205.     assert forall|addr: int| #[trigger] v.allocated_frames.contains(addr) <==>
206.         (v.refcounts.contains_key(addr) && v.refcounts[addr] > 0) by {
207.         if v.allocated_frames.contains(addr) {
208.             let i = choose|i: int|
209.                 #[trigger] inner.bitmap@.set_bits.contains(i) && addr == frame_addr_of(i);
210.             assert(0 <= i < nbits);
211.             assert(addr == i * ps);
212.             assert(addr / ps == i) by (nonlinear_arith) requires addr == i * ps, ps > 0;
213.             assert(v.refcounts[addr] == inner.refcount@[i]);
214.             assert(inner.refcount@[i] > 0);
215.         }
216.     };
217. 
218.     // Free frames carry no refcount entry.
219.     assert forall|addr: int| #[trigger] v.free_frames.contains(addr) implies
220.         !v.refcounts.contains_key(addr) by {
221.         let i = choose|i: int|
222.             0 <= i < nbits && !(#[trigger] inner.bitmap@.set_bits.contains(i))
223.                 && addr == frame_addr_of(i);
224.         assert(addr == i * ps);
225.         if v.refcounts.contains_key(addr) {
226.             let j = choose|j: int|
227.                 #[trigger] inner.bitmap@.set_bits.contains(j) && addr == frame_addr_of(j);
228.             assert(addr == j * ps);
229.             assert(i == j) by (nonlinear_arith) requires ps > 0, i * ps == j * ps;
230.             assert(false);
231.         }
232.     };
233. 
234.     // Refcount values are within the u8 range.
235.     assert forall|addr: int| v.refcounts.contains_key(addr) implies
236.         0 < v.refcounts[addr] <= 255 by {
237.         let i = choose|i: int|
238.             #[trigger] inner.bitmap@.set_bits.contains(i) && addr == frame_addr_of(i);
239.         assert(0 <= i < nbits);
240.         assert(addr == i * ps);
241.         assert(addr / ps == i) by (nonlinear_arith) requires addr == i * ps, ps > 0;
242.         assert(v.refcounts[addr] == inner.refcount@[i]);
243.         assert(inner.bitmap@.set_bits.contains(i));
244.         assert(0 < inner.refcount@[i] <= 255);
245.     };
246. }
247. 
248. // A refcount update at an already-set index `fnn` to a new positive value preserves `internal_inv`
249. // and changes the view only by setting `pa`'s (= `fnn * ps`) refcount to the new value. Used by
250. // `share` (increment) and the shared-still-owned case of `free` (decrement that stays positive).
251. proof fn lemma_refcount_bump(old_inner: &Inner, new_inner: &Inner, fnn: int, new_val: u8, pa: int)
252.     requires
253.         old_inner.inv(),
254.         new_inner.bitmap == old_inner.bitmap,
255.         new_inner.refcount@ == old_inner.refcount@.update(fnn, new_val),
256.         0 <= fnn < old_inner.bitmap@.num_bits,
